function rfdude_pll_generate_script(config_s, filename, overwrite)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Retain the human-created parameter layout/comments in generated aa_run files.
if nargin<3
    overwrite=false;
end
[directory,name,extension]=fileparts(filename);
if isempty(directory)
    directory=pwd;
end
if ~strcmp(extension,'.m') || ~isvarname(name) || ~strncmp(name,'aa_run',6)
    error('Use an aa_run... filename that is a valid MATLAB/Octave script name');
end
if exist(directory,'dir')~=7
    error('Script directory does not exist');
end
[ok,attributes]=fileattrib(directory);
if ~ok
    error('Cannot resolve script directory');
end
directory=attributes.Name;
filename=fullfile(directory,[name extension]);
if exist(filename,'file') && ~overwrite
    error('Script exists; overwrite must be explicitly confirmed');
end
rfdude_pll_validate_configuration(config_s,directory);
tool_directory=fileparts(mfilename('fullpath'));
source=fileread(fullfile(tool_directory,'aa_RunPllDesign_XXXX.m'));
lines=regexp(source,'\r\n|\n','split');
body={ ...
    ['% ' name '.m -- PLL setup and run']; ...
    '% Generated by GitHub Copilot under Lance Lascari''s direction.'; ...
    '% Parameter layout/comments retained from the human-created aa_RunPllDesign_XXXX.m.'; ...
    '% GNU Octave first; MATLAB compatibility is a maintained goal.'; ...
    '% Edit the explicit assignments below as you would a copied example.'; ...
    '% The GUI is not needed to run or modify this saved script.'; ...
    '% Run by script name from its directory in the Octave GUI command window.'; ...
    '% Startup clears the command window, closes figures and clears the workspace.'};
for k=1:numel(lines)
    if strcmp(strtrim(lines{k}),'rfdude_pll_oct_0p1')
        break;
    end
    line=lines{k};
    if strncmp(line,'%-when the "bUseVCO/TCXOFromFile"',32)
        line='% File input details: reference file replaces noise; VCO file replaces noise and Kvco.';
        body{end+1,1}='% Requested output frequency and F_tcxo_Hz remain explicit system inputs in file mode.';
    end
    token=regexp(line,'^pll_inputs_s\.(\w+)\s*=','tokens','once');
    if ~isempty(token)
        body{end+1,1}=['% ' input_comment(token{1})];
        comment=regexp(line,'%.*$','match','once');
        line=['pll_inputs_s.' token{1} '=' literal(config_s.pll_inputs_s.(token{1})) ';'];
        if ~isempty(comment)
            line=[line ' ' comment];
        end
    end
    body{end+1,1}=line;
end
relative=relative_directory(directory,tool_directory);
body=[body; { ...
    '%% run control -- edit here for a single pass or a design-target sweep'; ...
    '% Single pass uses the assignments above; sweep mode changes one design target.'; ...
    '% Each point is synthesized, then the component overrides above are applied.'; ...
    '% Example: fix R3/C3 with third-pole-only override and sweep BW_desired_Hz.'; ...
    '% This redesigns C1/C2/R2 at each bandwidth; it is NOT a tolerance sweep.'; ...
    '% A full override with a bandwidth/phase-margin target sweep is rejected.'; ...
    '% For a large sweep, consider disabling core plots AND figure exports above.'; ...
    '% The dataset includes curves and metrics for later cc_pll_data_viewer browsing.'}];
o=config_s.run_options_s;
for name=fieldnames(o).'
    if strcmp(name{1},'base_directory')
        continue;
    end
    body{end+1,1}=['% ' option_comment(name{1})];
    body{end+1,1}=['run_options_s.' name{1} '=' literal(o.(name{1})) ';'];
end
body=[body; { ...
    ''; ...
    '%% locate the analysis tools and run the configured experiment'; ...
    '% Relative noise/results paths are resolved from THIS script directory.'; ...
    '% Keep the relative tool path valid if moving the script to another folder.'; ...
    'run_options_s.base_directory=fileparts(mfilename(''fullpath''));'; ...
    ['pll_tool_directory=fullfile(run_options_s.base_directory,' literal(relative) ');']; ...
    'addpath(pll_tool_directory);'; ...
    '% A fresh workspace is used per point; the core still performs the PLL analysis.'; ...
    '% Saved outputs: <results basename>_data.mat and <results basename>_cases/.'; ...
    '% Pending/failed cases retain status; existing results are overwritten by default.'; ...
    'PLL_DATA_s=rfdude_pll_run(pll_inputs_s,run_options_s);'; ...
    ''; ...
    '%% basic single-pass results (same names as the human-created runner)'; ...
    '% The runner already calculated these using the existing PN helper methods.'; ...
    '% pn_struct contains output carrier frequency, offset grid and total SSB noise.'; ...
    '% int_noise is double-sided RMS phase error (rad); EVM_tot = 20*log10(int_noise).' ; ...
    '% Residual FM is in Hz and retains the existing unverified-method warning.'; ...
    '% Sweep results instead live in PLL_DATA_s.cases, one entry per requested point.'; ...
    'if ~run_options_s.bRunSweep'; ...
    '    pn_struct=PLL_DATA_s.cases{1}.pn_struct;'; ...
    '    int_noise=PLL_DATA_s.cases{1}.integrated_noise_rad'; ...
    '    EVM_tot=PLL_DATA_s.cases{1}.EVM_dB'; ...
    '    residual_FM_Hz=PLL_DATA_s.cases{1}.residual_FM_Hz'; ...
    'end'; ...
    ''; ...
    '% To reopen stored results later: cc_pll_data_viewer(''path_to_saved_data.mat'')'; ...
    '% Select individual points/overlays, or compare noise/transient surfaces and metrics.'; ...
    '% Disabled/not-settled transient results are not fabricated zero lock times.'; ...
    ''}];
text=sprintf('%s\n',body{:});
temporary=[tempname(directory) '.m'];
cleanup=onCleanup(@() remove_temporary(temporary));
[fid,message]=fopen(temporary,'w');
if fid<0
    error('Cannot create script: %s',message);
end
count=fwrite(fid,text,'char');
closed=fclose(fid);
if count~=numel(text) || closed~=0
    error('Could not completely write script: %s',filename);
end
[ok,message]=movefile(temporary,filename,'f');
if ~ok
    error('Cannot save generated script: %s',message);
end
end

function text=input_comment(name)
switch name
    case 'fout_desired_Hz', text='Desired final output carrier (Hz), after the ideal output multiplier/divider.';
    case 'mult', text='Output ratio: 1 = bare VCO, 2 = multiply by 2, 0.5 = divide by 2; VCO target = fout_desired_Hz/mult.';
    case 'Fref_Hz', text='PFD comparison frequency (Hz), not the oscillator carrier; sets N and sampling delay.';
    case 'Kvco_Hz_volt', text='Manual VCO tuning sensitivity (Hz/volt); ignored when VCO file input supplies kvco.';
    case 'Kphi_A_cycle', text='Charge-pump current / phase-detector gain (A/cycle); 1e-3 represents 1 mA.';
    case 'BW_desired_Hz', text='Requested loop bandwidth (Hz); synthesized target, not guaranteed achieved crossover.';
    case 'PM_desired_deg', text='Requested phase margin (degrees); synthesis compensates for the PFD delay.';
    case 'ATTEN_dB', text='Additional attenuation request (dB) for third-pole synthesis at the PFD frequency; keep modest and positive.';
    case 'bUseTCXOFromFile', text='Reference noise source: 0 = manual noise below, 1 = FileTCXO pn_struct data.';
    case 'F_tcxo_Hz', text='Reference oscillator carrier (Hz), used for R and noise scaling EVEN with file input.';
    case 'FileTCXO', text='Reference noise MAT filename; requires pn_struct. Relative path is from this run script.';
    case 'Ntcxo_ref_dBc', text='Manual reference SSB phase noise (dBc/Hz) at Ftcxo_ref_offset_Hz; ignored in reference file mode.';
    case 'Ftcxo_ref_offset_Hz', text='Offset frequency (Hz) of the manual reference noise anchor; existing noise_basic model supplies its shape.';
    case 'bUseVCOFromFile', text='VCO source: 0 = manual noise/Kvco, 1 = file noise and pn_struct.kvco.';
    case 'FileVCO', text='VCO noise MAT filename; requires pn_struct including kvco (Hz/volt). File fc does not replace the target.';
    case 'Nvco_ref_dBc', text='Manual open-loop VCO SSB noise (dBc/Hz) at Fvco_ref_offset_Hz; ignored in VCO file mode.';
    case 'Fvco_ref_offset_Hz', text='Offset frequency (Hz) of the manual VCO noise anchor; not the carrier or loop bandwidth.';
    case 'Npd_ref_dBc', text='Phase-detector noise figure of merit (dBc/Hz); core adds 10*log10(PFD frequency) and divider scaling.';
    case 'def_filename', text='Results basename (.mat); choose a new name for a new experiment. Leading _ keeps outputs git-ignored.';
    case 'fstart_main_Hz', text='Lowest phase-noise/loop-analysis OFFSET frequency (Hz); must be positive.';
    case 'fstop_main_Hz', text='Highest OFFSET frequency (Hz); noise-file endpoints are extended if measured data is narrower.';
    case 'fsweep_main_pts', text='Number of logarithmically spaced offset points (integer >=2); affects measured crossover resolution.';
    case 'filter_override', text='1 = replace ALL synthesized C1/C2/R2/C3/R3 with values below; do not also enable third-pole-only.';
    case 'filter_override_3rdpole_only', text='1 = hold R3/C3 below while C1/C2/R2 are synthesized; useful for bandwidth design-target sweeps.';
    case 'CC1', text='Shunt capacitor at the charge-pump node (F); used only with full override. 1e-9 = 1 nF.';
    case 'CC2', text='Capacitor in the shunt R2/C2 branch (F); used only with full override.';
    case 'RR2', text='Resistor in the shunt R2/C2 branch (ohm); used only with full override.';
    case 'CC3', text='Capacitor at the VCO tuning node (F); used with full OR third-pole-only override.';
    case 'RR3', text='Series resistor from charge-pump node to VCO tuning node (ohm); used with either override mode.';
    case 'bSaveFigs', text='Master per-point figure-export switch; PDF/JPG settings below only apply when this is 1.';
    case 'bSaveFigsPDF', text='Export original analysis figures as PDF when bSaveFigs=1; independent of viewer launch.';
    case 'bSaveFigsJPG', text='Export original analysis figures as JPG when bSaveFigs=1; each sweep point gets its own filenames.';
    case 'bDoTransient', text='1 = small-signal frequency-step estimate; linear model, no saturation or cycle slips.';
    case 'transient_delta_f_Hz', text='Starting frequency offset (Hz); both models share it. Large steps need nonlinear interpretation.';
    case 'transient_tmax_s', text='Simulation duration (seconds) for both transient models; extend if a case has not settled.';
    case 'transient_points', text='Small-signal time samples (integer >=2); increases settling-time resolution, not nonlinear step density.';
    case 'transient_ftol_Hz', text='Settling band (+/- Hz) around target; estimates require all remaining samples inside this band.';
    case 'bDoTransientNonlinear', text='1 = independent PFD/charge-pump acquisition simulation, including cycle slips; can run without small-signal.';
    case 'transient_nl_steps_per_ref', text='Nonlinear steps per PFD period (integer >=10); time step = 1/(Fref_Hz*this value).';
    case 'transient_nl_fvco_min_Hz', text='Absolute lower VCO tuning frequency (Hz), not output frequency after mult; -Inf disables the lower limit.';
    case 'transient_nl_fvco_max_Hz', text='Absolute upper VCO tuning frequency (Hz); Inf disables the upper limit; limits must contain the VCO target.';
    case 'pn_ylimits', text='Phase-noise plot limits [lower upper] (dBc/Hz); does not clip saved data or change integration.';
    case 'bWriteCSVtable', text='1 = per-point CSV with system settings, filter values and total phase-noise table.';
    otherwise, error('No generated-script explanation for PLL input: %s',name);
end
end

function text=option_comment(name)
switch name
    case 'bRunSweep', text='0 = one pass using pll_inputs_s above; 1 = repeat for sweep_values with the same component overrides.';
    case 'sweep_parameter', text='Design target field: BW_desired_Hz, PM_desired_deg, Fref_Hz, Kphi_A_cycle or fout_desired_Hz.';
    case 'sweep_values', text='Target values in that field''s units; e.g. [1000 2000 4000] Hz for bandwidth, or 1000:1000:4000.';
    case 'integration_lower_Hz', text='Lower phase-noise integration OFFSET (Hz); lies within the saved frequency grid.';
    case 'integration_upper_Hz', text='Upper integration OFFSET (Hz); same limits at every point so RMS phase/EVM/residual FM are comparable.';
    case 'noise_offsets_Hz', text='Offsets (Hz) to compare in summary plots; noise is interpolated in dBc/Hz versus log10(offset).';
    case 'bShowCorePlots', text='1 = original analysis windows per point; 0 = hidden/closed core windows. Does not disable figure exports.';
    case 'bEnableDataViewer', text='1 = launch cc_pll_data_viewer after the run; 0 = save results only, for later independent viewing.';
    case 'bOverwriteResults', text='1 = replace an existing dataset and matching case files (default); set to 0 to protect them. Older surplus case files remain.';
    otherwise, error('No generated-script explanation for run option: %s',name);
end
end

function text=literal(value)
if ischar(value)
    text=['''' strrep(value,'''','''''') ''''];
else
    text=mat2str(double(value),17);
end
end

function remove_temporary(filename)
if exist(filename,'file')==2
    delete(filename);
end
end

function relative=relative_directory(from,to)
from_parts=strsplit(from,filesep);
to_parts=strsplit(to,filesep);
k=1;
while k<=min(numel(from_parts),numel(to_parts)) && strcmp(from_parts{k},to_parts{k})
    k=k+1;
end
parts=[repmat({'..'},1,numel(from_parts)-k+1) to_parts(k:end)];
if isempty(parts)
    relative='.';
else
    relative=fullfile(parts{:});
end
end
